//! TLC's message catalogue (`EC.java` + `MP.java`), framing, and exit-status map.
//!
//! `catalog.rs` is generated by `xtask gen-fidelity` from the pinned `EC.java`/`MP.java`:
//! every code, its exit status, and every template that is plain text. Templates whose
//! `getMessage0` case computes text are hand-written in `computed.rs`; the generated code
//! names them, so a missing one fails the build.
//!
//! The message *class* (`@!@!@STARTMSG code:class`) is not a property of the code in TLC:
//! it is chosen by the call (`printError`, `printWarning`, `printMessage`, `printState`,
//! `printTLCBug`). So it is chosen here by the [`Report`] method, not stored in the table.

mod catalog;
mod computed;

pub use catalog::Ec;

use std::collections::BTreeSet;
use std::io::Write;
use std::sync::Mutex;

/// `EC.ExitStatus`. Process exit code is [`ExitStatus::code`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(i32)]
pub enum ExitStatus {
    Success = 0,
    /// `TLC.main` on a bad argument (not in `EC.ExitStatus`, but observable).
    UsageError = 1,
    ViolationAssumption = 10,
    ViolationDeadlock = 11,
    ViolationSafety = 12,
    ViolationLiveness = 13,
    ViolationAssert = 14,
    FailureSpecEval = 75,
    FailureSafetyEval = 76,
    FailureLivenessEval = 77,
    ErrorSpecParse = 150,
    ErrorConfigParse = 151,
    ErrorStatespaceTooLarge = 152,
    ErrorSystem = 153,
    Error = 255,
}

impl ExitStatus {
    pub fn code(self) -> i32 {
        self as i32
    }
}

/// `MP` message classes as printed in tool-mode framing.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum MsgClass {
    None = 0,
    Error = 1,
    TlcBug = 2,
    Warning = 3,
    State = 4,
}

/// A `getMessage0` case, before `%i%` replacement.
#[derive(Clone, Copy)]
pub enum Template {
    Static(&'static str),
    Computed(fn(&[&str], &RenderCx) -> String),
    /// No case for the code: TLC's `default` branch.
    Default,
}

/// What a computed template may depend on besides its parameters.
pub struct RenderCx {
    pub class: MsgClass,
    /// `TLCGlobals.tool`.
    pub tool_mode: bool,
    /// `MP.now()`: the formatted wall-clock time, or `NOW` under `-Dtlc2.output.MP.noTimestamps`.
    pub now: String,
    /// `-Dtlc2.output.MP.noDebug` (sic): adds the fingerprint to state messages.
    pub debug: bool,
}

/// `MP.getMessage0`: the message body without framing.
///
/// Parameters are replaced in order, each placeholder everywhere in the buffer, which also
/// rewrites placeholders that an earlier parameter's text introduced (`MP.replaceString`).
/// TLC stops at the first `null` parameter; callers here never pass one.
pub fn render(ec: Ec, params: &[&str], cx: &RenderCx) -> String {
    let mut body = match ec.template() {
        Template::Static(s) => s.to_string(),
        Template::Computed(f) => f(params, cx),
        Template::Default => "Wrong invocation of TLC error printer. Error code not found.".to_string(),
    };
    for (i, p) in params.iter().enumerate() {
        let placeholder = format!("%{}%", i + 1);
        if body.contains(&placeholder) {
            body = body.replace(&placeholder, p);
        }
    }
    body
}

/// `MP.getMessage(class, code, params)`: [`render`] plus tool-mode framing or the
/// non-tool class prefix. The first-warning hint is added by [`Reporter`], which owns the
/// warning history it depends on.
pub fn frame(class: MsgClass, ec: Ec, body: &str, tool_mode: bool) -> String {
    if tool_mode {
        format!("@!@!@STARTMSG {}:{} @!@!@\n{body}\n@!@!@ENDMSG {} @!@!@", ec.code(), class as u8, ec.code())
    } else {
        let prefix = match class {
            MsgClass::Error => "Error: ",
            MsgClass::TlcBug => "TLC Bug: ",
            MsgClass::State => "State ",
            MsgClass::Warning => "Warning: ",
            MsgClass::None => "",
        };
        format!("{prefix}{body}")
    }
}

/// A warning listed in `-messagesAsErrors`: TLC throws instead of printing
/// (`Assert.fail(code, params)` in `printWarning`), so the caller must fail with `ec`.
#[derive(Debug, PartialEq, Eq)]
pub struct WarningAsError {
    pub ec: Ec,
    pub message: String,
}

/// Sink for everything TLC prints through `MP`/`ToolIO`. `Sync` so worker threads can print
/// (`Print`, `PrintT`, warnings) the way TLC's `synchronized` `MP` methods do.
pub trait Report: Sync {
    /// `printMessage`.
    fn message(&self, ec: Ec, params: &[&str]);
    /// `printError`; returns `ec` as TLC does. Errors are never suppressed.
    fn error(&self, ec: Ec, params: &[&str]) -> Ec;
    /// `printTLCRuntimeException` for an exception with parameters (`Assert.fail(ec, params)`):
    /// an error, but one that `-suppressMessages` hides (`MP.java:1843`).
    fn runtime_exception(&self, ec: Ec, params: &[&str]) -> Ec;
    /// `MP.getMessage(ec, params)`: the class-0 message, framed in tool mode, as exception
    /// texts carry it (`Assert.fail` builds its message this way).
    fn text(&self, ec: Ec, params: &[&str]) -> String;
    /// `printWarning`.
    fn warning(&self, ec: Ec, params: &[&str]) -> Result<(), WarningAsError>;
    /// `printState`.
    fn state(&self, ec: Ec, params: &[&str]);
    /// `printTLCBug`.
    fn tlc_bug(&self, ec: Ec, params: &[&str]);
    /// Unframed text, printed as is (SANY's own lines, `Print` output).
    fn raw(&self, text: &str);
}

/// Formats the current time for `MP.now()`.
pub type Now = Box<dyn Fn() -> String + Send + Sync>;

pub struct ReporterConfig {
    pub tool_mode: bool,
    /// `!-nowarning` (`TLCGlobals.warn`).
    pub warnings_enabled: bool,
    /// `-suppressMessages`, TLC range.
    pub suppressed: Vec<Ec>,
    /// `-messagesAsErrors`, TLC range.
    pub as_errors: Vec<Ec>,
    pub debug: bool,
    pub now: Now,
}

/// The one [`Report`] implementation and the only writer of TLC's stdout.
pub struct Reporter<'w> {
    inner: Mutex<ReporterInner<'w>>,
    cfg: ReporterConfig,
}

struct ReporterInner<'w> {
    out: Box<dyn Write + Send + 'w>,
    /// `MP.warningHistory`: full warning texts already printed.
    warning_history: BTreeSet<String>,
}

impl<'w> Reporter<'w> {
    pub fn new(out: Box<dyn Write + Send + 'w>, cfg: ReporterConfig) -> Self {
        Reporter { inner: Mutex::new(ReporterInner { out, warning_history: BTreeSet::new() }), cfg }
    }

    fn message_text(&self, class: MsgClass, ec: Ec, params: &[&str]) -> String {
        let cx = RenderCx { class, tool_mode: self.cfg.tool_mode, now: (self.cfg.now)(), debug: self.cfg.debug };
        frame(class, ec, &render(ec, params, &cx), self.cfg.tool_mode)
    }

    fn is_suppressed(&self, ec: Ec) -> bool {
        self.cfg.suppressed.contains(&ec)
    }

    /// `ToolIO.out.println`. A failed write is ignored, as `PrintStream` does.
    fn println(inner: &mut ReporterInner<'_>, text: &str) {
        let _ = writeln!(inner.out, "{text}");
        let _ = inner.out.flush();
    }

    fn print_unless_suppressed(&self, class: MsgClass, ec: Ec, params: &[&str]) {
        if !self.is_suppressed(ec) {
            let text = self.message_text(class, ec, params);
            Self::println(&mut self.inner.lock().expect("reporter lock"), &text);
        }
    }
}

impl Report for Reporter<'_> {
    fn message(&self, ec: Ec, params: &[&str]) {
        self.print_unless_suppressed(MsgClass::None, ec, params);
    }

    fn error(&self, ec: Ec, params: &[&str]) -> Ec {
        let text = self.message_text(MsgClass::Error, ec, params);
        Self::println(&mut self.inner.lock().expect("reporter lock"), &text);
        ec
    }

    fn runtime_exception(&self, ec: Ec, params: &[&str]) -> Ec {
        self.print_unless_suppressed(MsgClass::Error, ec, params);
        ec
    }

    fn text(&self, ec: Ec, params: &[&str]) -> String {
        self.message_text(MsgClass::None, ec, params)
    }

    fn warning(&self, ec: Ec, params: &[&str]) -> Result<(), WarningAsError> {
        if self.cfg.as_errors.contains(&ec) {
            let cx = RenderCx { class: MsgClass::Error, tool_mode: self.cfg.tool_mode, now: (self.cfg.now)(), debug: self.cfg.debug };
            return Err(WarningAsError { ec, message: render(ec, params, &cx) });
        }
        if !self.cfg.warnings_enabled {
            return Ok(());
        }
        let mut inner = self.inner.lock().expect("reporter lock");
        let mut text = self.message_text(MsgClass::Warning, ec, params);
        if !self.cfg.tool_mode && inner.warning_history.is_empty() {
            text.push_str("\n(Use the -nowarning option to disable this warning.)");
        }
        if inner.warning_history.insert(text.clone()) && !self.is_suppressed(ec) {
            Self::println(&mut inner, &text);
        }
        Ok(())
    }

    fn state(&self, ec: Ec, params: &[&str]) {
        self.print_unless_suppressed(MsgClass::State, ec, params);
    }

    fn tlc_bug(&self, ec: Ec, params: &[&str]) {
        self.print_unless_suppressed(MsgClass::TlcBug, ec, params);
    }

    fn raw(&self, text: &str) {
        let mut inner = self.inner.lock().expect("reporter lock");
        let _ = inner.out.write_all(text.as_bytes());
        let _ = inner.out.flush();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::{Arc, Mutex as StdMutex};

    /// A `Write` whose contents the test can read back.
    #[derive(Clone, Default)]
    struct Captured(Arc<StdMutex<Vec<u8>>>);

    impl Write for Captured {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.0.lock().unwrap().extend_from_slice(buf);
            Ok(buf.len())
        }
        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }

    impl Captured {
        fn text(&self) -> String {
            String::from_utf8(self.0.lock().unwrap().clone()).unwrap()
        }
    }

    fn reporter(out: &Captured, tool_mode: bool, suppressed: Vec<Ec>, as_errors: Vec<Ec>) -> Reporter<'static> {
        let cfg = ReporterConfig {
            tool_mode,
            warnings_enabled: true,
            suppressed,
            as_errors,
            debug: false,
            now: Box::new(|| "NOW".into()),
        };
        Reporter::new(Box::new(out.clone()), cfg)
    }

    /// Recorded from TLC (`MP.printWarning` four times): duplicates are detected on the full
    /// text, which includes the first-warning hint, so the second "a" is printed again.
    #[test]
    fn warnings_dedup_on_full_text_including_the_first_hint() {
        let out = Captured::default();
        let r = reporter(&out, false, vec![], vec![]);
        for p in ["a", "a", "b", "b"] {
            r.warning(Ec::TLC_FEATURE_UNSUPPORTED, &[p]).unwrap();
        }
        assert_eq!(out.text(), "Warning: a\n(Use the -nowarning option to disable this warning.)\nWarning: a\nWarning: b\n");
    }

    #[test]
    fn suppression_hides_messages_but_not_errors() {
        let out = Captured::default();
        let r = reporter(&out, true, vec![Ec::TLC_COMPUTING_INIT, Ec::TLC_DEADLOCK_REACHED], vec![]);
        r.message(Ec::TLC_COMPUTING_INIT, &[]);
        r.error(Ec::TLC_DEADLOCK_REACHED, &[]);
        assert_eq!(out.text(), "@!@!@STARTMSG 2114:1 @!@!@\nDeadlock reached.\n@!@!@ENDMSG 2114 @!@!@\n");
    }

    #[test]
    fn runtime_exceptions_are_suppressible_errors() {
        let out = Captured::default();
        let r = reporter(&out, true, vec![Ec::TLC_INTEGER_TOO_BIG], vec![]);
        assert_eq!(r.runtime_exception(Ec::TLC_INTEGER_TOO_BIG, &["2147483648"]), Ec::TLC_INTEGER_TOO_BIG);
        r.runtime_exception(Ec::TLC_PARSING_FAILED, &[]);
        assert_eq!(out.text(), "@!@!@STARTMSG 3002:1 @!@!@\nParsing or semantic analysis failed.\n@!@!@ENDMSG 3002 @!@!@\n");
    }

    /// The nested part of TLC's 2105 output (`div_by_zero` in the conformance corpus).
    #[test]
    fn exception_text_is_framed_as_class_none() {
        let out = Captured::default();
        let r = reporter(&out, true, vec![], vec![]);
        let text = r.text(Ec::TLC_MODULE_DIVISION_BY_ZERO, &[]);
        assert_eq!(text, "@!@!@STARTMSG 2179:0 @!@!@\nThe second argument of \\div is 0.\n@!@!@ENDMSG 2179 @!@!@");
        assert!(out.text().is_empty());
    }

    #[test]
    fn messages_as_errors_turn_a_warning_into_a_failure() {
        let out = Captured::default();
        let r = reporter(&out, true, vec![], vec![Ec::TLC_FEATURE_UNSUPPORTED]);
        let err = r.warning(Ec::TLC_FEATURE_UNSUPPORTED, &["x"]).unwrap_err();
        assert_eq!(err.ec, Ec::TLC_FEATURE_UNSUPPORTED);
        assert!(out.text().is_empty());
    }

    #[test]
    fn exit_status_follows_ec_exit_status() {
        assert_eq!(Ec::TLC_INVARIANT_VIOLATED_BEHAVIOR.exit_status(), ExitStatus::ViolationSafety);
        assert_eq!(Ec::CFG_LEXICAL_ERROR.exit_status(), ExitStatus::ErrorConfigParse);
        assert_eq!(Ec::TLC_COMPUTING_INIT.exit_status(), ExitStatus::Error);
        assert_eq!(Ec::NO_ERROR.exit_status(), ExitStatus::Success);
    }
}
